import hashlib
import json
import os
import subprocess
import sys
import threading
import time
import types
from datetime import datetime, timezone
from pathlib import Path

root = Path(__file__).resolve().parent
now = lambda: datetime.now(timezone.utc).isoformat()
rows = []
for image in ['main-client.py.txt', 'reference-client.py.txt']:
    module = types.ModuleType(image)
    source = (root / image).read_bytes()
    exec(compile(source, str(root / image), 'exec'), module.__dict__)
    for case in ['closed-request', 'closed-notify', 'healthy-request', 'reply-eof-request']:
        cell = root / 'cells' / (image.split('-')[0] + '-' + case)
        cell.mkdir(parents=True, exist_ok=False)
        mode = 'closed' if case.startswith('closed') else ('reply-eof' if case.startswith('reply-eof') else 'healthy')
        argv = [sys.executable, str(root / 'peer.py'), mode, str(cell)]
        row = {'image': image, 'image_sha256': hashlib.sha256(source).hexdigest(), 'case': case,
               'started_utc': now(), 'driver_pid': os.getpid(), 'argv': argv}
        client = None
        try:
            client = module.CodexAppServerClient(argv, journal_path=cell / 'journal.jsonl')
            row['peer_pid'] = client.process.pid
            deadline = time.monotonic() + 2
            while not (cell / 'ready').exists():
                if time.monotonic() >= deadline or client.process.poll() is not None:
                    raise RuntimeError('peer readiness STOP')
                time.sleep(.001)
            if mode == 'closed':
                client._reader.join(timeout=2)
                if client._reader.is_alive() or client._closed is not True:
                    raise RuntimeError('known terminal reader precondition STOP')
            if mode == 'reply-eof':
                original_write = client._write
                def wait_after_write(message):
                    original_write(message)
                    client._reader.join(timeout=2)
                    if client._reader.is_alive() or client._closed is not True:
                        raise RuntimeError('queued valid response/EOF precondition STOP')
                client._write = wait_after_write
            row['before'] = {'closed': client._closed, 'reader_alive': client._reader.is_alive(),
                             'peer_poll': client.process.poll(),
                             'journal_bytes': (cell / 'journal.jsonl').stat().st_size}
            row['call_started_utc'] = now()
            try:
                if case == 'closed-notify':
                    value = client.notify('inert/notify', {'token': 'inert-known-eof'})
                else:
                    value = client.request('inert/request', {'token': 'inert-known-eof'}, timeout=.5)
                row['outcome'] = {'kind': 'return', 'value': value}
            except Exception as error:
                row['outcome'] = {'kind': 'exception', 'type': type(error).__name__, 'message': str(error)}
            row['call_ended_utc'] = now()
            row['after'] = {'closed': client._closed, 'reader_alive': client._reader.is_alive(),
                            'peer_poll': client.process.poll()}
        finally:
            if client is not None:
                client.process.stdin.close()
                try:
                    client.process.wait(timeout=2)
                except subprocess.TimeoutExpired:
                    client.process.kill()
                    client.process.wait(timeout=2)
                    row['cleanup_kill'] = True
                client.close(timeout=2)
                stderr = client.process.stderr.read()
                (cell / 'peer-stderr.txt').write_text(stderr)
                for stream in [client.process.stdin, client.process.stdout, client.process.stderr]:
                    stream.close()
                row['cleanup'] = {'peer_exit': client.process.returncode, 'reader_alive': client._reader.is_alive(),
                                  'journal_closed': client._journal.closed,
                                  'streams_closed': [stream.closed for stream in [client.process.stdin, client.process.stdout, client.process.stderr]],
                                  'stderr_bytes': len(stderr.encode())}
            row['ended_utc'] = now()
            for name in ['wire.bin', 'journal.jsonl', 'peer-stderr.txt']:
                path = cell / name
                if path.exists():
                    data = path.read_bytes()
                    row[name] = {'bytes': len(data), 'sha256': hashlib.sha256(data).hexdigest()}
            rows.append(row)
            (root / 'RAW.json').write_text(json.dumps(rows, indent=2) + '\n')
print(json.dumps({'rows': len(rows), 'driver_pid': os.getpid()}))
